import{z as l,x as o,o as t,c as d,q as r,j as i,D as E,d as A,s as B,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"伴随算法微分 AAD","description":"","frontmatter":{"title":"伴随算法微分 AAD","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/aad-adjoint.md","filePath":"quant/aad-adjoint.md","lastUpdated":1791413859000}'),p={name:"quant/aad-adjoint.md"};function m(u,a,D,h,b,c){const n=o("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="伴随算法微分-aad" tabindex="-1">伴随算法微分 AAD <a class="header-anchor" href="#伴随算法微分-aad" aria-label="Permalink to &quot;伴随算法微分 AAD&quot;">​</a></h1><div class="epigraph"><p>一次伴随反向扫过，可以得到价值对所有输入的梯度；成本与一次定价同阶，而不是与参数个数成正比。</p><footer>—— Giles and Glasserman, Smoking Adjoints, Risk, 2006</footer></div><p><a href="/quant/structured-notes">上一课</a>把结构拆成腿。缺口立刻变成：<strong>腿一多、参数一多，有限差分希腊值爆算力。</strong> 伴随算法微分（adjoint algorithmic differentiation, AAD）把计算图倒过来，一次反向传播给出全部一阶敏感度。后课路径导数与似然比写的是蒙特卡洛里另一套梯度；本课先把伴随当工程默认，不把自动微分当成「深度学习课」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bump-and-revalue：每个 Vega 桶、每个曲线节点 bump 一次，定价次数随参数维数 \\(n\\) 线性涨。结构票据、XVA、保证金的输入是整条曲面与整条利率曲线，\\(n\\) 成百上千。问题是梯度的计算图已经在定价时建过一遍：每一步算术都有局部偏导，反向把 \\(\\partial V/\\partial(\\mathrm{output})\\) 乘回去，得到 \\(\\partial V/\\partial(\\mathrm{input})\\)。Giles–Glasserman 把这套从计算数学引进蒙特卡洛定价，对象是金融里的「一阶希腊值全要」。</p><p><span class="marginnote">算一笔账感受差距：\\(n=1000\\) 个曲线节点时，bump-and-revalue 要完整定价 \\(1001\\) 次；伴随模式只需正向定价一次，加一次成本同阶的反向扫过，合计约等于两三次定价。这就是百倍到千倍的算力差距来源。</span></p><p>AAD 给的是<strong>同一条实现路径（或同一棵树上）价值对输入的导数</strong>，不是新的风险测度。模型错了，伴随只是把错的价值微分得更快。</p><h3 id="正向与反向的成本不对称" tabindex="-1">正向与反向的成本不对称 <a class="header-anchor" href="#正向与反向的成本不对称" aria-label="Permalink to &quot;正向与反向的成本不对称&quot;">​</a></h3><p>正向模式（tangent）适合输入少、输出多；反向模式（adjoint）适合输入多、输出少。定价几乎总是标量输出 \\(V\\)，输入是市场数据向量，故反向是对的。实现要保存正向的中间量（磁带），内存与检查点是工程约束，不是理论装饰。</p><p><span class="marginnote">AAD 的一阶不自动给出稳定的二阶。Gamma、Vanna 要用二阶伴随、前向-反向混合，或对伴随再做一次差分。把一阶伴随当 Hessian 用会静默地错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对定价函数做算子重载或源码变换，每条算术记录局部 Jacobian。反向从 \\(\\bar V=1\\) 扫到市场数据。蒙特卡洛：每条路径反向，再平均——这是路径wise 梯度的伴随实现，与后课的路径导数同一对象，只是算得更快。间断支付（数字、障碍）的路径wise 导数在触发处失效，要平滑、或改用似然比，或把数字换成价差。</p><p>曲线与曲面应以节点为输入，伴随直接给出桶风险，不必再对每个节点 bump。这与后课 <a href="/quant/vega-buckets">Vega 桶</a> 的报告层对齐。</p><p><span class="marginnote">「磁带」（tape）就是把定价过程中每一步算术及其局部偏导按执行顺序录下来的记录：反向时倒着放一遍，把敏感度逐层乘回去。可以想象成先把做菜全程录像，再倒放找出每种配料对最终味道的贡献比例。</span></p>',14)),(t(),i(s,null,{default:E(()=>[B(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E7%AE%97%E4%BB%B7%E5%80%BC%E5%AF%B9%E4%BB%80%E4%B9%88%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20S%5B%22%E8%BE%93%E5%85%A5%20n%20%E6%9D%A1%E6%9B%B2%E7%BA%BF%E4%B8%8E%E6%9B%B2%E9%9D%A2%20%E8%BE%93%E5%87%BA%E5%8D%95%E4%B8%AA%E6%A0%87%E9%87%8F%20V%22%5D%0A%20%20S%20--%3E%20T%5B%22%E6%AD%A3%E5%90%91%E6%A8%A1%E5%BC%8F%20%E6%AF%8F%E4%B8%AA%E8%BE%93%E5%85%A5%E5%8D%95%E7%8B%AC%E8%BF%87%E4%B8%80%E9%81%8D%22%5D%0A%20%20T%20--%3E%20C%5B%22%E6%88%90%E6%9C%AC%20n%20%E6%AC%A1%E5%AE%8C%E6%95%B4%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20S%20--%3E%20A%5B%22%E5%8F%8D%E5%90%91%E6%A8%A1%E5%BC%8F%20%E4%BB%8E%20V%20%E5%8F%8D%E6%89%AB%E4%B8%80%E9%81%8D%22%5D%0A%20%20A%20--%3E%20D%5B%22%E6%88%90%E6%9C%AC%E7%BA%A6%E4%B8%80%E8%87%B3%E4%B8%A4%E6%AC%A1%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20C%20--%3E%20E%5B%22n%20%E6%88%90%E7%99%BE%E4%B8%8A%E5%8D%83%E6%97%B6%E7%AE%97%E5%8A%9B%E7%88%86%E7%82%B8%22%5D%0A%20%20D%20--%3E%20F%5B%22%E5%85%A8%E9%83%A8%E6%A1%B6%E9%A3%8E%E9%99%A9%E4%B8%80%E6%AC%A1%E4%BA%A7%E5%87%BA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"上面这张图回答的问题是：为什么输入多、输出少的定价问题天然属于反向模式——选模式只看输入输出哪个多，与模型本身无关。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"链式法则把 \\(\\mathrm{d}V\\) 写成中间变量微分的线性组合。正向积累切向量，反向积累伴随向量。金融定价的计算图深（模拟步、折现、聚合），但宽度主要在市场数据，反向一次扫过就够。与机器学习里的反向传播是同一数学，应用对象是希腊值与校准的 Jacobian，不是神经网络权重。",-1)),(t(),i(s,null,{default:E(()=>[B(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20In%5B%22%E5%B8%82%E5%9C%BA%E6%95%B0%E6%8D%AE%20%E6%9B%B2%E7%BA%BF%20%E6%9B%B2%E9%9D%A2%22%5D%20--%3E%20Fwd%5B%22%E6%AD%A3%E5%90%91%E5%AE%9A%E4%BB%B7%20%E5%BD%95%E9%9F%B3%E5%B8%A6%22%5D%0A%20%20Fwd%20--%3E%20V%5B%22%E6%A0%87%E9%87%8F%E4%BB%B7%E5%80%BC%20V%22%5D%0A%20%20V%20--%3E%20Adj%5B%22%E5%8F%8D%E5%90%91%E4%BC%B4%E9%9A%8F%20%E4%B8%80%E6%AC%A1%E6%89%AB%E8%BF%87%22%5D%0A%20%20Adj%20--%3E%20G%5B%22%E5%85%A8%E9%83%A8%E4%B8%80%E9%98%B6%E5%B8%8C%E8%85%8A%E5%80%BC%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>间断、停时、最小/最大、提前行权的指示函数会让路径wise 导数偏或方差爆炸。美式回归的伴随要穿过回归系数，实现复杂。并行与检查点、GPU 上的磁带，是工程瓶颈。监管报告若要求独立的 bump 验证，AAD 与差分应对账，不能只交伴随数字。</p><p><span class="marginnote">对账时看到 AAD 与 bump 数字有微小差异，初学者容易以为实现出了 bug；实际上差分步长选得不好（太大引入高阶偏差，太小撞上浮点舍入噪声），两者本就允许这个量级的误差带。真正的 bug 往往表现为某个桶方向性错掉，而不是整体小偏差。</span></p><p>本课不把 AAD 写成可以替代模型审查。它加速的是已选定模型的导数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反向伴随一次给出价值对全部输入的一阶导数，成本与一次定价同阶。</li><li>间断支付要平滑或改方法；二阶不是免费的。</li><li>输出是桶风险的自然来源，接到 Vega 桶与校准。</li><li>出处：Giles and Glasserman, <em>Risk</em>, 2006；算法微分见 Griewank and Walther, <em>Evaluating Derivatives</em>。</li></ul>',6))])}const g=l(p,[["render",m]]);export{C as __pageData,g as default};
